import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_empty(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 5, 7), ([], 0, 0), ([], 5, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_and_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b, -2, 0 ", "c,3, \t"]) == [
        event("a", 1, True), event("b", -2, False), event("c", 3, None),
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,record,at,all", "a,1,0"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, False)]
    assert parse_transcript_log(["", "  # comment"]) == []
    # A hash in a field is not an inline comment.
    assert parse_transcript_log(["a#b,1,1"]) == [event("a#b", 1, True)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        event("b", 9, True), event("a", 2, True), event("c", 1, None),
        event("b", 2, False), event("a", 2, None),
    ]
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_dense_range():
    events = [
        event("before", 0, True), event("a", 1, True), event("b", 1, True),
        event("c", 2, False), event("d", 2, None), event("e", 4, True),
        event("after", 5, True),
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_monitor_summary_uses_pooled_rate_calendar_days_and_nonempty_groups(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 2, None),
                  event("d", 2, False), event("e", 4, True), event("f", 5, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "b": [{"flagged": False}],
        "a": [],
    }
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": None, "b": 0.0, "z": 0.5}
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 2, 3, 0, 4], 2),
     ([1, -1, 2, 3, -2, 4], 2), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
